// Service Worker registration + version info. The SW (dist/sw.js, generated by scripts/make-sw.mjs) precaches the whole app + data.
export interface VersionInfo {
  version: string;
  files: number;
  builtAt: string;
}

export function registerSW() {
  if (!import.meta.env.PROD || !('serviceWorker' in navigator)) return;
  window.addEventListener('load', () => {
    // Relative URL: resolves against the page, so it works at the root and under a GitHub Pages sub-path.
    navigator.serviceWorker
      .register('./sw.js', { updateViaCache: 'none' })
      .then((reg) => reg.update()) // always check for a newer build when the app is opened
      .catch((e) => console.warn('SW registration failed', e));
  });
}

export async function getVersionInfo(): Promise<VersionInfo | null> {
  try {
    const res = await fetch(import.meta.env.BASE_URL + 'version.json', { cache: 'no-cache' });
    return res.ok ? ((await res.json()) as VersionInfo) : null;
  } catch {
    return null;
  }
}

/** 'ready' = a service worker controls this page and its cache for the current version exists. */
export async function offlineStatus(version?: string): Promise<'ready' | 'installing' | 'unsupported'> {
  if (!('serviceWorker' in navigator) || !import.meta.env.PROD) return 'unsupported';
  if (!navigator.serviceWorker.controller) return 'installing';
  if (version && 'caches' in window && !(await caches.has(`english-reader-${version}`))) return 'installing';
  return 'ready';
}
